package de.igslandstuhl.database.attendance;import static org.junit.jupiter.api.Assertions.*;import com.google.gson.*;import java.io.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;
class AttendanceSchemaTest{@Test void routeAndNavigationMetadataAreValidJson()throws Exception{JsonParser.parseString(resource("/meta/paths/get_paths.json"));JsonParser.parseString(resource("/meta/paths/post_paths.json"));JsonParser.parseString(resource("/meta/navigation/navigation_elements.json"));}@Test void arcanumPagesAreTemplatedButQrDisplaysStayStandalone()throws Exception{JsonObject paths=JsonParser.parseString(resource("/meta/paths/get_paths.json")).getAsJsonObject();for(String path:new String[]{"/attendance","/attendance-admin","/attendance-checkin"})assertEquals("TemplatingFileRequestHandler",paths.getAsJsonObject(path).get("handler_type").getAsString());for(String path:new String[]{"/attendance-display","/attendance-display/arrival","/attendance-display/la","/attendance-display/ws","/attendance-display/nawi","/attendance-display/input1","/attendance-display/gn"})assertEquals("FileRequestHandler",paths.getAsJsonObject(path).get("handler_type").getAsString());assertTrue(resource("/html/teacher/attendance.html").contains("%[teacher_other_nav]"));assertTrue(resource("/html/admin/attendance-admin.html").contains("%[admin_nav]"));assertTrue(resource("/html/user/attendance-checkin.html").contains("%[student_nav]"));}@Test void schemaIsAppendOnlyEventModelWithoutLegacyTokenTables()throws Exception{assertTrue(resource("/sql/tables/attendance_events.sql").contains("FOREIGN KEY(student_id)"));assertTrue(resource("/sql/tables/attendance_events.sql").contains("FOREIGN KEY(location_id)"));assertNull(getClass().getResource("/sql/tables/attendance_tokens.sql"));assertNull(getClass().getResource("/sql/tables/attendance_checkins.sql"));}private static String resource(String p)throws Exception{try(InputStream in=AttendanceSchemaTest.class.getResourceAsStream(p)){assertNotNull(in);return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}}
